using System.Text.Json;
using System.Text;
namespace BeastCloud;

public sealed partial class Cloud
{
    static void MapRecords(WebApplication app)
    {
        app.MapGet("/api/records", (Database d, string? type, string? q) => d.Rows("SELECT * FROM records WHERE ($t='' OR type=$t) AND (title LIKE $q OR body LIKE $q) ORDER BY modified DESC LIMIT 1000", ("$t", type ?? ""), ("$q", "%" + (q ?? "") + "%")));
        app.MapPut("/api/records/{id}", async (HttpContext c, Cloud x, string id, JsonElement j) =>
        {
            if (!System.Text.RegularExpressions.Regex.IsMatch(id, "^[a-f0-9]{32}$")) throw new ArgumentException("Invalid record identity"); await Locked(x.disk, () =>
            {
                var type = S(j, "type"); if (type is not ("note" or "task" or "event")) throw new ArgumentException("Invalid record type"); var title = S(j, "title") ?? "Untitled"; if (title.Length > 300) throw new ArgumentException("Title too long"); var body = j.GetProperty("body").GetRawText(); if (body.Length > 1024 * 1024) throw new ArgumentException("Record too large");
                if (type == "event") { var b = j.GetProperty("body"); if (!DateTimeOffset.TryParse(S(b, "start"), out var start) || !DateTimeOffset.TryParse(S(b, "end"), out var end) || end < start) throw new ArgumentException("Valid event start and end are required"); _ = TimeZoneInfo.FindSystemTimeZoneById(S(b, "timezone") ?? "UTC"); if (S(b, "repeat") is string repeat && repeat is not ("none" or "daily" or "weekly" or "monthly")) throw new ArgumentException("Supported repeats: daily, weekly, monthly"); if (L(b, "count", 1) < 1 || L(b, "count", 1) > 366) throw new ArgumentException("Recurrence count must be 1–366"); }
                var existing = x.db.Rows("SELECT * FROM records WHERE id=$id", ("$id", id)).FirstOrDefault(); if (existing != null && L(j, "revision", -1) != Convert.ToInt64(existing["revision"])) throw new InvalidOperationException("Record changed; reload before saving"); x.db.Transaction(d => { if (existing != null) Database.Exec(d, "INSERT INTO record_versions VALUES($v,$id,$t,$b,$m)", ("$v", Id()), ("$id", id), ("$t", existing["title"]), ("$b", existing["body"]), ("$m", existing["modified"])); Database.Exec(d, "INSERT INTO records VALUES($id,$t,$n,$b,$m,1) ON CONFLICT(id) DO UPDATE SET title=$n,body=$b,modified=$m,revision=revision+1", ("$id", id), ("$t", type), ("$n", title), ("$b", body), ("$m", Database.Now)); }); x.db.Job("record-index", id); x.db.Audit(Actor(c), type + ".saved", id); return Task.CompletedTask;
            }); return Results.Ok(x.db.Rows("SELECT * FROM records WHERE id=$id", ("$id", id))[0]);
        });
        app.MapDelete("/api/records/{id}", async (HttpContext c, Cloud x, string id) => { await Locked(x.disk, () => { x.db.Execute("DELETE FROM records WHERE id=$id", ("$id", id)); x.db.Execute("DELETE FROM search WHERE id=$id", ("$id", id)); x.db.Audit(Actor(c), "record.deleted", id); return Task.CompletedTask; }); return Results.Ok(); });
        app.MapGet("/api/records/{id}/versions", (Database d, string id) => d.Rows("SELECT * FROM record_versions WHERE recordId=$id ORDER BY modified DESC", ("$id", id)));
        app.MapGet("/api/records/export", (Database d) => Results.File(Encoding.UTF8.GetBytes(JsonSerializer.Serialize(d.Rows("SELECT * FROM records"))), "application/json", "beastcloud-records.json"));
        app.MapGet("/api/calendar/export", (Database d) => Results.File(Encoding.UTF8.GetBytes(Calendar.Export(d.Rows("SELECT * FROM records WHERE type='event'"))), "text/calendar", "beastcloud.ics"));
        app.MapPost("/api/calendar/import", async (Cloud x, JsonElement j) => { var events = Calendar.Import(S(j, "text") ?? ""); await Locked(x.disk, () => { x.db.Transaction(c => { foreach (var e in events) { Database.Exec(c, "INSERT INTO records VALUES($id,'event',$t,$b,$m,1)", ("$id", Id()), ("$t", e.title), ("$b", JsonSerializer.Serialize(e.body)), ("$m", Database.Now)); } }); foreach (var r in x.db.Rows("SELECT id FROM records WHERE type='event'")) x.db.Job("record-index", (string)r["id"]!); return Task.CompletedTask; }); return Results.Ok(new { imported = events.Count }); });
        app.MapGet("/api/search", (Database d, string q, string? type, string? tag, string? after, string? location) => { if (string.IsNullOrWhiteSpace(q)) return []; var term = '"' + q.Replace("\"", "\"\"") + '"'; return d.Rows("SELECT s.id,s.type,s.title,s.content,s.tags FROM search s LEFT JOIN items i ON i.id=s.id LEFT JOIN records r ON r.id=s.id WHERE search MATCH $q AND (i.deleted IS NULL) AND (i.id IS NOT NULL OR r.id IS NOT NULL) AND ($t='' OR s.type=$t) AND s.tags LIKE $tag AND COALESCE(i.modified,r.modified)>=$a AND ($loc='' OR s.id IN (WITH RECURSIVE tree(id) AS (SELECT $loc UNION ALL SELECT items.id FROM items JOIN tree ON items.parent=tree.id) SELECT id FROM tree)) LIMIT 100", ("$q", term), ("$t", type ?? ""), ("$tag", "%" + (tag ?? "") + "%"), ("$a", after ?? ""), ("$loc", location ?? "")); });
    }
}
public static class Calendar
{
    static string Esc(string s) => s.Replace("\\", "\\\\").Replace("\r", "").Replace("\n", "\\n").Replace(",", "\\,").Replace(";", "\\;");
    static string Unesc(string s) => s.Replace("\\n", "\n").Replace("\\,", ",").Replace("\\;", ";").Replace("\\\\", "\\");
    public static string Export(List<Dictionary<string, object?>> rows) { var b = new StringBuilder("BEGIN:VCALENDAR\r\nVERSION:2.0\r\nPRODID:-//BeastCloud//Local Calendar//EN\r\n"); foreach (var r in rows) { var j = JsonDocument.Parse((string)r["body"]!).RootElement; string Date(string k) => DateTimeOffset.Parse(Cloud.S(j, k)!).UtcDateTime.ToString("yyyyMMdd'T'HHmmss'Z'"); b.Append($"BEGIN:VEVENT\r\nUID:{r["id"]}@beastcloud\r\nDTSTAMP:{DateTime.UtcNow:yyyyMMdd'T'HHmmss'Z'}\r\nDTSTART:{Date("start")}\r\nDTEND:{Date("end")}\r\nSUMMARY:{Esc((string)r["title"]!)}\r\nDESCRIPTION:{Esc(Cloud.S(j, "text") ?? "")}\r\n"); if (Cloud.S(j, "repeat") is string repeat && repeat != "none") b.Append($"RRULE:FREQ={repeat.ToUpperInvariant()};COUNT={Cloud.L(j, "count", 1)}\r\n"); b.Append("END:VEVENT\r\n"); } return b.Append("END:VCALENDAR\r\n").ToString(); }
    public static List<(string title, object body)> Import(string text) { if (text.Length > 1024 * 1024) throw new ArgumentException("Calendar import too large"); var result = new List<(string, object)>(); Dictionary<string, string>? e = null; foreach (var line in text.Replace("\r\n ", "").Replace("\r", "").Split('\n')) { if (line == "BEGIN:VEVENT") { e = new(); continue; } if (line == "END:VEVENT" && e != null) { DateTimeOffset Parse(string key) { if (!e.TryGetValue(key, out var val)) throw new ArgumentException("UTC DTSTART and DTEND required"); if (!DateTimeOffset.TryParseExact(val, "yyyyMMdd'T'HHmmss'Z'", System.Globalization.CultureInfo.InvariantCulture, System.Globalization.DateTimeStyles.AssumeUniversal, out var dt)) throw new ArgumentException("Only UTC date-time iCalendar imports are supported"); return dt; } var repeat = "none"; int count = 1; if (e.TryGetValue("RRULE", out var rule)) { var parts = rule.Split(';').Select(p => p.Split('=')).ToDictionary(p => p[0], p => p[1]); if (parts.Keys.Any(k => k is not ("FREQ" or "COUNT")) || !parts.ContainsKey("COUNT")) throw new ArgumentException("Recurrence import requires FREQ and COUNT only"); repeat = parts["FREQ"].ToLowerInvariant(); if (repeat is not ("daily" or "weekly" or "monthly") || !int.TryParse(parts["COUNT"], out count) || count < 1 || count > 366) throw new ArgumentException("Unsupported recurrence"); } var start = Parse("DTSTART"); var end = Parse("DTEND"); if (end < start) throw new ArgumentException("Invalid event duration"); result.Add((Unesc(e.GetValueOrDefault("SUMMARY", "Untitled")), new { start, end, timezone = "UTC", repeat, count, text = Unesc(e.GetValueOrDefault("DESCRIPTION", "")) })); e = null; continue; } if (e != null) { int pos = line.IndexOf(':'); if (pos > 0) { var k = line[..pos]; if (k.Contains(';') || k is "EXDATE" or "RDATE" or "RECURRENCE-ID") throw new ArgumentException("Unsupported iCalendar property; nothing imported"); e[k] = line[(pos + 1)..]; } } } if (e != null || result.Count == 0) throw new ArgumentException("No complete events found"); return result; }
}
